def show(n):
    if n > 0:
        show(n - 1)
        print(n)
show(3)

def total(n):
    if n == 0:
        return 0
    return n + total(n - 1)
print(total(4))

def fact(n):
    if n == 0:
        return 1
    return n * fact(n - 1)
print(fact(4))

